$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$modulePath = Join-Path $pkg "ahos\candidate_triage.py"
$testPath = Join-Path $pkg "tests\test_candidate_triage.py"
$backlogPath = Join-Path $pkg "AHOS_BACKLOG.json"
$python = Join-Path $root ".venv\Scripts\python.exe"
$liveStore = Join-Path $root "runtime\live_intake\public_candidates.jsonl"

if (-not (Test-Path $liveStore)) { throw "Live candidate store not found." }
if (-not (Test-Path $python)) { throw "Python venv not found." }

[IO.File]::WriteAllBytes($modulePath, [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes($testPath, [Convert]::FromBase64String(""))

$b = Get-Content $backlogPath -Raw | ConvertFrom-Json
if (-not ($b.tasks | Where-Object { $_.id -eq "AHOS-019" })) {
    $b.tasks += [pscustomobject]@{
        id = "AHOS-019"
        title = "Separate real business leads from employee job postings"
        status = "pending"
        risk = "low"
        authority = "B"
        requires_owner_approval = $false
        task = "Refine local opportunity triage so highly technical full-time employment listings are not mislabeled as holding business opportunities. Require explicit freelance, contractor, consulting, or similar project signals for business-lead promotion. Keep all processing local and free."
    }
    [IO.File]::WriteAllText(
        $backlogPath,
        ($b | ConvertTo-Json -Depth 12),
        (New-Object System.Text.UTF8Encoding($false))
    )
}

Write-Host "=== AHOS-019 STRICT BUSINESS LEAD TRIAGE ==="
Write-Host "Running tests locally. NO OpenAI and NO network calls."

$oldPythonPath = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg
    & $python -m pytest -q
    $testExit = $LASTEXITCODE
} finally {
    Pop-Location
    $env:PYTHONPATH = $oldPythonPath
}
if ($testExit -ne 0) { throw "AHOS-019 tests failed." }

$code = @'
from pathlib import Path
from collections import Counter
from ahos.candidate_triage import triage_store

root = Path(r"__ROOT__")
results = triage_store(
    root / "runtime" / "live_intake" / "public_candidates.jsonl",
    root / "runtime" / "live_intake" / "candidate_triage.jsonl",
)

counts = Counter(item.disposition.value for item in results)
print("")
print("=== STRICT TRIAGE RESULT ===")
print("TOTAL:", len(results))
for key in ("business_lead", "review", "tech_job", "low_fit", "human_job"):
    print(key.upper() + ":", counts.get(key, 0))

print("")
print("=== BUSINESS LEADS / REVIEW ===")
shown = 0
for item in results:
    if item.disposition.value in ("business_lead", "review"):
        print("%3d [%s] %s" % (item.score, item.disposition.value, item.title))
        print("    " + item.item_url)
        shown += 1
        if shown >= 25:
            break
if shown == 0:
    print("No true business/project leads found in current job-board sample.")
'@
$code = $code.Replace("__ROOT__", $root.Replace("\", "\\"))

$oldPythonPath = $env:PYTHONPATH
try {
    $env:PYTHONPATH = $pkg
    $code | & $python -
    if ($LASTEXITCODE -ne 0) { throw "Strict live triage failed." }
} finally {
    $env:PYTHONPATH = $oldPythonPath
}

$b = Get-Content $backlogPath -Raw | ConvertFrom-Json
$t = $b.tasks | Where-Object { $_.id -eq "AHOS-019" } | Select-Object -First 1
$t.status = "completed"
if ($t.PSObject.Properties.Name -contains "completed_at") {
    $t.completed_at = [DateTime]::UtcNow.ToString("o")
} else {
    $t | Add-Member -NotePropertyName completed_at -NotePropertyValue ([DateTime]::UtcNow.ToString("o"))
}
[IO.File]::WriteAllText(
    $backlogPath,
    ($b | ConvertTo-Json -Depth 12),
    (New-Object System.Text.UTF8Encoding($false))
)

git -C $ws add ahos_core/ahos/candidate_triage.py ahos_core/tests/test_candidate_triage.py ahos_core/AHOS_BACKLOG.json
git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" commit -m "fix(ahos): separate business leads from employee jobs"
if ($LASTEXITCODE -ne 0) { throw "git commit failed." }

git -C $ws push origin HEAD
if ($LASTEXITCODE -ne 0) { throw "git push failed." }

Write-Host ""
Write-Host "=== AHOS-019 COMPLETE ==="
Write-Host "Full AHOS tests: PASS"
Write-Host "Backlog: AHOS-019 -> completed"
Write-Host "Git push: PASS"
Write-Host "OpenAI API calls: 0"
Write-Host "Network calls: 0"
